MAX_STEPS = 10
COST_CAP = 0.50
PRICE_PER_1K = 0.003

def fake_model(step):
    # finishes on the 3rd step; each step 'costs' 1000 tokens
    if step == 2:
        return {"done": True, "answer": "42", "tokens": 1000}
    return {"done": False, "action": "search", "tokens": 1000}

def run(model):
    spend = 0.0
    for step in range(MAX_STEPS):
        out = model(step)
        spend += (out["tokens"] / 1000) * PRICE_PER_1K
        if spend > COST_CAP:
            return {"status": "stopped", "reason": "cost cap", "spend": spend}
        if out["done"]:
            return {"status": "done", "answer": out["answer"],
                    "steps": step + 1, "spend": round(spend, 4)}
    return {"status": "stopped", "reason": "max steps"}

print(run(fake_model))

MAX_STEPS = 20

def spinning_model(_):
    # never finishes, never varies -> classic no-progress loop
    return {"done": False, "action": "search[same query]"}

def run(model):
    recent = []
    for step in range(MAX_STEPS):
        out = model(recent)
        recent.append(out["action"])
        if len(recent) >= 3 and recent[-1] == recent[-2] == recent[-3]:
            return {"status": "stopped", "reason": "no progress",
                    "steps": step + 1}
        if out["done"]:
            return {"status": "done", "steps": step + 1}
    return {"status": "stopped", "reason": "max steps", "steps": MAX_STEPS}

print(run(spinning_model))
